                        ]
                    },
                    scores: {
                        A: { coherence: 5, awareness: -10, reputation: -8 },
                        B: { coherence: 12, awareness: 15, reputation: 15 },
                        C: { coherence: 10, awareness: 12, reputation: 12 },
                        D: { coherence: 8, awareness: 10, reputation: 5 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 6: The Board',
                        narrative: 'You are invited to present at a board audit committee meeting. Over the previous five scenarios, your decisions have generated a confidential ethics portfolio — a documented record of every judgment call and its organizational consequence. The board has received an anonymous report alleging improper conduct across environmental, procurement, and data practices. The board chair asks you directly: Give me your honest assessment of this operation ethical health.',
                        options: [
                            'A) Give a fully transparent briefing, including disclosure of all decisions made, their rationale, and unresolved ethical risks.',
