        _getLang() {
            try {
                if (window.mySimulation && window.mySimulation.currentLanguage) return window.mySimulation.currentLanguage;
            } catch(e) {}
            var html = document.documentElement;
            if (html && html.lang) return html.lang.substring(0, 2);
            return 'es';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.SCENARIOS.length - 1);
            var scenario = this.SCENARIOS[idx];
            var lang = this._getLang();
            var data = scenario[lang] || scenario.en;

            var titleEl = document.getElementById('scenarioTitle');
            if (titleEl) titleEl.innerHTML = data.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = data.narrative;

            var labels = ['A', 'B', 'C', 'D'];
            for (var i = 0; i < labels.length; i++) {
                var labelEl = document.getElementById('option' + labels[i] + 'Label');
                if (labelEl) labelEl.innerHTML = data.options[i];
            }

            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        var adapter = new EthicalCrossroadsAdapter();
        window.mySimulation = new USF.SimulationFramework();
        // Re-sync the scenario/options after UNDO: the host player's undo() rewinds
        // domainState + the period counter but never re-renders the sim-owned dilemma,
        // so without this the player would see the wrong scenario's options after undo.
        var undoBtn = document.getElementById('undoBtn');
        if (undoBtn) undoBtn.addEventListener('click', function () {
            setTimeout(function () { try { adapter._updateBriefing(window.mySimulation.state); } catch (e) {} }, 0);
        });
        window.mySimulation.initialize(adapter, {
            simulationType: 'ethical_crossroads',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

